// @generated by:gauntlet run:godseye-local-orchestration
import { randomUUID } from "node:crypto";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import {
  type OrchestrationFixture,
  orchestrationFixture,
} from "./helpers/orchestration-fixture.js";

describe("owner clarification retains evidence and requires a new exact approval", () => {
  let f: OrchestrationFixture;
  beforeEach(async () => {
    f = await orchestrationFixture();
  });
  afterEach(async () => {
    await f.store.close();
  });

  it("T-AC-708 creates a new pending suffix without replaying an executed prefix", async () => {
    const research = f.research;
    const original = await f.prepare({
      steps: [
        research,
        {
          id: "question",
          dependsOn: ["research"],
          kind: "clarification",
          question: "Which variant should continue?",
        },
        { ...research, id: "followup", dependsOn: ["question"] },
      ],
    });
    await f.approve(original);
    await f.tick();
    await f.work();
    await f.tick();
    const waiting = await f.detail(original.plan.id);
    expect(waiting.state).toBe("waiting_clarification");
    const key = randomUUID(),
      answer = "<script>globalThis.__orchestrationXss=true</script>";
    const input = { expectedHash: original.plan.hash, stepId: "question", answer };

    const continuation = await f.infrastructure.orchestration.answer(
      f.freshOwner(),
      original.plan.id,
      input,
      key,
    );
    expect(
      await f.infrastructure.orchestration.answer(f.freshOwner(), original.plan.id, input, key),
    ).toEqual(continuation);
    expect(continuation.state).toBe("pending");
    expect(continuation.plan.id).not.toBe(original.plan.id);
    expect(continuation.plan.hash).not.toBe(original.plan.hash);
    expect(continuation.plan.supersedesId).toBe(original.plan.id);
    expect(continuation.plan.steps.map((step) => step.step.id)).not.toContain("research");
    expect(continuation.plan.steps.find((step) => step.step.id === "question")?.step).toMatchObject(
      { kind: "clarification", answer },
    );
    expect(JSON.stringify(continuation.plan.steps)).toContain(answer);
    expect((await f.detail(original.plan.id)).children[0]?.taskId).toBe(
      waiting.children[0]?.taskId,
    );
    await f.tick();
    expect(f.agentProvider.submissions).toHaveLength(1);
    expect(await f.infrastructure.foundation.listRuns(f.freshOwner())).toHaveLength(1);
    await f.approve(continuation);
    for (let n = 0; n < 3; n++) {
      await f.tick();
      await f.work();
    }
    await f.tick();
    expect((await f.detail(continuation.plan.id)).state).toBe("succeeded");
    expect(f.agentProvider.submissions).toHaveLength(2);
  });

  it("T-AC-708 refuses answers against changed hashes or nonwaiting steps", async () => {
    const original = await f.prepare({
      steps: [{ id: "question", dependsOn: [], kind: "clarification", question: "Which variant?" }],
    });
    const answer = { expectedHash: original.plan.hash, stepId: "question", answer: "Variant A" };
    await expect(
      f.infrastructure.orchestration.answer(f.freshOwner(), original.plan.id, answer, randomUUID()),
    ).rejects.toMatchObject({ status: 409 });
    await f.approve(original);
    await f.tick();
    await expect(
      f.infrastructure.orchestration.answer(
        f.freshOwner(),
        original.plan.id,
        { ...answer, expectedHash: "0".repeat(64) },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ status: 409 });
    expect((await f.infrastructure.orchestration.overview(f.freshOwner())).plans).toHaveLength(1);
  });

  it("T-AC-708 retains a terminal clarification answer in a new pending exact plan", async () => {
    const original = await f.prepare({
      steps: [{ id: "question", dependsOn: [], kind: "clarification", question: "Which variant?" }],
    });
    await f.approve(original);
    await f.tick();
    const continuation = await f.infrastructure.orchestration.answer(
      f.freshOwner(),
      original.plan.id,
      { expectedHash: original.plan.hash, stepId: "question", answer: "Variant A" },
      randomUUID(),
    );
    expect(continuation.state).toBe("pending");
    expect(JSON.stringify(continuation.plan.steps)).toContain("Variant A");
    await f.approve(continuation);
    await f.tick();
    await f.tick();
    expect((await f.detail(continuation.plan.id)).state).toBe("succeeded");
    expect(f.agentProvider.submissions).toHaveLength(0);
  });
});
